function maximumLength(s) {
  const count = new Map();
  for (let start = 0; start < s.length; start++) {
    let piece = '';
    for (let end = start; end < s.length && s[end] === s[start]; end++) {
      piece += s[end];
      count.set(piece, (count.get(piece) ?? 0) + 1);
    }
  }
  let best = -1;
  for (const [piece, occurrences] of count) {
    if (occurrences >= 3) {
      best = Math.max(best, piece.length);
    }
  }
  return best;
}

