function maximumLength(s) {
  // Try lengths from longest to shortest and count every placement of each repeated letter.
  const letters = [...new Set(s)];
  for (let length = s.length; length >= 1; length--) {
    for (const letter of letters) {
      const target = letter.repeat(length);
      let found = 0;
      for (let i = 0; i + length <= s.length; i++) {
        if (s.slice(i, i + length) === target) found++;
      }
      if (found >= 3) return length;
    }
  }
  return -1;
}

