function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const n = size === 'small' ? int(3, 12) : int(40, 50);
  const alphabet = 'abcdefghijklmnopqrstuvwxyz'.slice(0, int(1, size === 'small' ? 3 : 4));
  const longest = int(1, size === 'small' ? 5 : 15);
  let s = '';
  while (s.length < n) {
    const letter = alphabet[int(0, alphabet.length - 1)];
    s += letter.repeat(Math.min(int(1, longest), n - s.length));
  }
  return [s];
}
